8013-6beb077b0071","label":"UCS Anacaona","workspace_id":"workspace_default","version":2,"previous_department":null,"previous_commune":null,"department":"Ouest","commune":null},{"id":"d235ab53-1367-480e-9214-2c5f70965dc7","label":"UCS du Cul-de-Sac / Frontière","workspace_id":"workspace_default","version":2,"previous_department":null,"previous_commune":null,"department":"Ouest","commune":null},{"id":"9016649f-e5fa-42c1-b9ee-f32ef348117a","label":"UCS Matheux","workspace_id":"workspace_default","version":2,"previous_department":null,"previous_commune":null,"department":"Ouest","commune":null},{"id":"a6dd2294-198b-403e-b29c-25d89fbb110d","label":"Unité d'Appui à la Décentralisation Sanitaire","workspace_id":"workspace_default","version":1,"previous_department":null,"previous_commune":null,"department":"Ouest","commune":null},{"id":"ee05a448-4cab-4214-8ebe-c582bd401bd9","label":"Unité de Communication et des Relations Publiques","workspace_id":"workspace_default","version":1,"previous_department":null,"previous_commune":null,"department":"Ouest","commune":null},{"id":"5633f0c6-f9cc-4ac6-8bf9-d074c0ee162d","label":"Unité de Coordination des Maladies Infectieuses et Transmissibles","workspace_id":"workspace_default","version":1,"previous_department":null,"previous_commune":null,"department":"Ouest","commune":null},{"id":"dac80f88-0341-4959-aade-ea5ca32cc5b7","label":"Unité de Santé Mentale","workspace_id":"workspace_default","version":1,"previous_department":null,"previous_commune":null,"department":"Ouest","commune":null},{"id":"394b340f-20d0-4e59-bdff-2b6725c6d8be","label":"Unité Juridique","workspace_id":"workspace_default","version":1,"previous_department":null,"previous_commune":null,"department":"Ouest","commune":null},{"id":"c09319b3-a6af-4ab2-ac3c-81e9a7eae791","label":"Unité Nationale de Gestion des Urgences Sanitaires","workspace_id":"workspace_default","version":1,"previous_department":null,"previous_commune":null,"department":"Ouest","commune":null}]$confirmed_geography$::jsonb;
  before_catalogue jsonb;
  before_contracts text;
  after_contracts text;
  valid_rows integer;
  updated_rows integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(739214805);
  -- Use the same lock as catalogue edits in the application.
  perform a.id from public.autocompletion a
    join jsonb_to_recordset(planned) as p(id text, label text, workspace_id text, version integer, previous_department text, previous_commune text, department text, commune text) on p.id=a.id
    order by a.id for update of a;
  select jsonb_agg(to_jsonb(a) order by a.id) into before_catalogue
    from public.autocompletion a where a.type='institution';
  select md5(coalesce(string_agg(to_jsonb(c)::text,'|' order by to_jsonb(c)::text),'')) into before_contracts
    from public.contrat c;
  select count(*) into valid_rows
    from public.autocompletion a join jsonb_to_recordset(planned) as p(id text, label text, workspace_id text, version integer, previous_department text, previous_commune text, department text, commune text) on p.id=a.id
    where a.type='institution' and a.label=p.label and a.workspace_id=p.workspace_id
      and a.version=p.version
      and a.department is not distinct from p.previous_department
      and a.commune is not distinct from p.previous_commune;
  if jsonb_array_length(planned)<>214 or valid_rows<>214 then
    raise exception 'Le lot confirmé ne correspond plus aux fiches actuelles (% / 214).',valid_rows;
  end if;
  update public.autocompletion a set department=p.department,commune=p.commune,updated_at=now()
    from jsonb_to_recordset(planned) as p(id text, label text, workspace_id text, version integer, previous_department text, previous_commune text, department text, commune text)
    where a.id=p.id and a.type='institution' and a.workspace_id=p.workspace_id and a.version=p.version;
  get diagnostics updated_rows=row_count;
  if updated_rows<>214 then raise exception 'Nombre de fiches modifiées incorrect : %.',updated_rows; end if;
  if exists (
    select 1 from jsonb_to_recordset(planned) as p(id text, label text, workspace_id text, version integer, previous_department text, previous_commune text, department text, commune text)
    left join public.autocompletion a on a.id=p.id
    where a.id is null or a.version is distinct from p.version+1
      or a.department is distinct from p.department or a.commune is distinct from p.commune
  ) then raise exception 'Vérification des localisations ou versions échouée.'; end if;
  -- Compare every protected field of all institutions, including untreated references.
  if (select count(*) from public.autocompletion where type='institution')<>jsonb_array_length(before_catalogue)
    or exists (
      select 1 from jsonb_array_elements(before_catalogue) b
      left join public.autocompletion a on a.id=b->>'id'
      where a.id is null or
        (to_jsonb(a)-'department'-'commune'-'version'-'updated_at') is distinct from
        (b-'department'-'commune'-'version'-'updated_at')
    ) then raise exception 'Un champ protégé du catalogue a changé.'; end if;
  if exists (
    select 1 from jsonb_array_elements(before_catalogue) b
    join public.autocompletion a on a.id=b->>'id'
    where not exists(select 1 from jsonb_to_recordset(planned) as p(id text, label text, workspace_id text, version integer, previous_department text, previous_commune text, department text, commune text) where p.id=a.id)
      and to_jsonb(a) is distinct from b
  ) then raise exception 'Une institution exclue du lot a changé.'; end if;
  select md5(coalesce(string_agg(to_jsonb(c)::text,'|' order by to_jsonb(c)::text),'')) into after_contracts
    from public.contrat c;
  if before_contracts is distinct from after_contracts then raise exception 'Les contrats ont changé.'; end if;
end;
$apply_geography$;
commit;
select count(*) as total_institutions,
 count(*) filter(where department is not null and department<>'') as departments,
 count(*) filter(where commune is not null and commune<>'') as communes
from public.autocompletion where type='institution';
